BEGIN;

CREATE TEMP TABLE _seed_ex (slug text, name text, name_it text, category text, subcategory text, difficulty text, note text, instructions text[], coaching_cues text[], common_mistakes text[], primary_muscles text[], secondary_muscles text[], equipment_tags text[], movement_pattern text, laterality text, source text, source_license text, football_relevance smallint, performance_goals text[], position_relevance text[], injury_prevention text[]) ON COMMIT DROP;

INSERT INTO _seed_ex (slug, name, name_it, category, subcategory, difficulty, note, instructions, coaching_cues, common_mistakes, primary_muscles, secondary_muscles, equipment_tags, movement_pattern, laterality, source, source_license, football_relevance, performance_goals, position_relevance, injury_prevention) VALUES
-- fed:Barbell_Squat · Back squat con bilanciere
('fed:Barbell_Squat', 'Barbell Squat', 'Back squat con bilanciere', 'Forza', 'Squat', 'Principiante', NULL, ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali', 'Lombari']::text[], ARRAY['Bilanciere']::text[], 'squat', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Forza massimale']::text[], '{}'::text[], '{}'::text[]),
-- fed:Front_Barbell_Squat · Front squat con bilanciere
('fed:Front_Barbell_Squat', 'Front Barbell Squat', 'Front squat con bilanciere', 'Forza', 'Squat', 'Avanzato', NULL, ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control.', 'Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor mainly with the middle of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Bilanciere']::text[], 'squat', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Forza massimale']::text[], '{}'::text[], '{}'::text[]),
-- fed:Goblet_Squat · Goblet squat
('fed:Goblet_Squat', 'Goblet Squat', 'Goblet squat', 'Forza', 'Squat', 'Principiante', NULL, ARRAY['Stand holding a light kettlebell by the horns close to your chest. This will be your starting position.', 'Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.', 'At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali', 'Spalle']::text[], ARRAY['Kettlebell']::text[], 'squat', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Bodyweight_Squat · Squat a corpo libero
('fed:Bodyweight_Squat', 'Bodyweight Squat', 'Squat a corpo libero', 'Forza', 'Squat', 'Principiante', NULL, ARRAY['Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.', 'Begin the movement by flexing your knees and hips, sitting back with your hips.', 'Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Glutei', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'squat', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Box_Squat · Box squat
('fed:Box_Squat', 'Box Squat', 'Box squat', 'Forza', 'Squat', 'Intermedio', NULL, ARRAY['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Adduttori', 'Polpacci', 'Glutei', 'Femorali', 'Lombari']::text[], ARRAY['Bilanciere']::text[], 'squat', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Forza massimale']::text[], '{}'::text[], '{}'::text[]),
-- fed:Dumbbell_Squat · Squat con manubri
('fed:Dumbbell_Squat', 'Dumbbell Squat', 'Squat con manubri', 'Forza', 'Squat', 'Principiante', NULL, ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali', 'Lombari']::text[], ARRAY['Manubri']::text[], 'squat', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Leg_Press · Leg press
('fed:Leg_Press', 'Leg Press', 'Leg press', 'Forza', 'Squat', 'Principiante', NULL, ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Macchina']::text[], 'squat', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Kettlebell_Pistol_Squat · Pistol squat con kettlebell
('fed:Kettlebell_Pistol_Squat', 'Kettlebell Pistol Squat', 'Pistol squat con kettlebell', 'Forza', 'Squat monopodalico', 'Avanzato', NULL, ARRAY['Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other.', 'Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you.', 'Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up.', 'Lower yourself again and repeat.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali', 'Spalle']::text[], ARRAY['Kettlebell']::text[], 'squat', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Split_Squats · Split squat
('fed:Split_Squats', 'Split Squats', 'Split squat', 'Forza', 'Affondi e split squat', 'Intermedio', NULL, ARRAY['Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.', 'As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei', 'Quadricipiti']::text[], '{}'::text[], 'lunge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Split_Squat_with_Dumbbells · Split squat con manubri
('fed:Split_Squat_with_Dumbbells', 'Split Squat with Dumbbells', 'Split squat con manubri', 'Forza', 'Affondi e split squat', 'Principiante', NULL, ARRAY['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Glutei', 'Femorali']::text[], ARRAY['Manubri']::text[], 'lunge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:One_Leg_Barbell_Squat · Affondo bulgaro con bilanciere
('fed:One_Leg_Barbell_Squat', 'One Leg Barbell Squat', 'Affondo bulgaro con bilanciere', 'Forza', 'Affondi e split squat', 'Avanzato', NULL, ARRAY['Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other.', 'Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest.', 'Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the flat bench. Your other foot should be stationary in front of you. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. Tip: Make sure your back is straight and chest is out while performing this exercise.', 'As you inhale, slowly lower your leg until your thigh is parallel to the floor. At this point, your knee should be over your toes. Your chest should be directly above the middle of your thigh.', 'Leading with the chest and hips and contracting the quadriceps, elevate your leg back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Bilanciere']::text[], 'lunge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Barbell_Lunge · Affondo con bilanciere
('fed:Barbell_Lunge', 'Barbell Lunge', 'Affondo con bilanciere', 'Forza', 'Affondi e split squat', 'Intermedio', NULL, ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Bilanciere']::text[], 'lunge', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Dumbbell_Lunges · Affondi con manubri
('fed:Dumbbell_Lunges', 'Dumbbell Lunges', 'Affondi con manubri', 'Forza', 'Affondi e split squat', 'Principiante', NULL, ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Manubri']::text[], 'lunge', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Bodyweight_Walking_Lunge · Affondi camminati a corpo libero
('fed:Bodyweight_Walking_Lunge', 'Bodyweight Walking Lunge', 'Affondi camminati a corpo libero', 'Forza', 'Affondi e split squat', 'Principiante', NULL, ARRAY['Begin standing with your feet shoulder width apart and your hands on your hips.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], '{}'::text[], 'lunge', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Dumbbell_Rear_Lunge · Affondo indietro con manubri
('fed:Dumbbell_Rear_Lunge', 'Dumbbell Rear Lunge', 'Affondo indietro con manubri', 'Forza', 'Affondi e split squat', 'Intermedio', NULL, ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.', 'Push up and go back to the starting position as you exhale. Tip: Use the ball of your feet to push in order to accentuate the quadriceps. To focus on the glutes, press with your heels.', 'Now repeat with the opposite leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Manubri']::text[], 'lunge', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Decelerazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Crossover_Reverse_Lunge · Affondo indietro incrociato
('fed:Crossover_Reverse_Lunge', 'Crossover Reverse Lunge', 'Affondo indietro incrociato', 'Mobilità e attivazione', 'Anche', 'Intermedio', NULL, ARRAY['Stand with your feet shoulder width apart. This will be your starting position.', 'Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg.', 'After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.']::text[], '{}'::text[], '{}'::text[], ARRAY['Lombari']::text[], ARRAY['Addominali', 'Abduttori', 'Glutei', 'Femorali', 'Quadricipiti']::text[], '{}'::text[], 'lunge', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità', 'Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Barbell_Side_Split_Squat · Affondo laterale con bilanciere
('fed:Barbell_Side_Split_Squat', 'Barbell Side Split Squat', 'Affondo laterale con bilanciere', 'Forza', 'Affondi e split squat', 'Principiante', NULL, ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position.', 'Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body.', 'Return to the starting position by extending the hip and knee of the lead leg. Breathe out as you perform this movement.', 'After performing the recommended amount of reps, repeat the movement with the opposite leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Femorali', 'Lombari']::text[], ARRAY['Bilanciere']::text[], 'lunge', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Cambio di direzione']::text[], '{}'::text[], ARRAY['Pubalgia/adduttori']::text[]),
-- fed:Barbell_Step_Ups · Step up con bilanciere
('fed:Barbell_Step_Ups', 'Barbell Step Ups', 'Step up con bilanciere', 'Forza', 'Step up', 'Intermedio', NULL, ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position.', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Bilanciere']::text[], 'lunge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Dumbbell_Step_Ups · Step up con manubri
('fed:Dumbbell_Step_Ups', 'Dumbbell Step Ups', 'Step up con manubri', 'Forza', 'Step up', 'Intermedio', NULL, ARRAY['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.', 'Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.', 'Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Manubri']::text[], 'lunge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Step-up_with_Knee_Raise · Step up con slancio del ginocchio
('fed:Step-up_with_Knee_Raise', 'Step-up with Knee Raise', 'Step up con slancio del ginocchio', 'Forza', 'Step up', 'Principiante', NULL, ARRAY['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.', 'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.', 'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Femorali', 'Quadricipiti']::text[], ARRAY['Corpo libero']::text[], 'lunge', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Barbell_Deadlift · Stacco da terra
('fed:Barbell_Deadlift', 'Barbell Deadlift', 'Stacco da terra', 'Forza', 'Stacchi', 'Intermedio', NULL, ARRAY['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[], '{}'::text[], '{}'::text[], ARRAY['Lombari']::text[], ARRAY['Polpacci', 'Avambracci', 'Glutei', 'Femorali', 'Dorsali', 'Dorso', 'Quadricipiti', 'Trapezi']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Forza massimale']::text[], '{}'::text[], '{}'::text[]),
-- fed:Trap_Bar_Deadlift · Stacco con trap bar
('fed:Trap_Bar_Deadlift', 'Trap Bar Deadlift', 'Stacco con trap bar', 'Forza', 'Stacchi', 'Principiante', NULL, ARRAY['For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.', 'Lower your hips, look forward with your head and keep your chest up.', 'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.', 'At the completion of the movement, lower the weight back to the ground under control.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Glutei', 'Femorali']::text[], ARRAY['Altro']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Forza massimale', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Sumo_Deadlift · Stacco sumo
('fed:Sumo_Deadlift', 'Sumo Deadlift', 'Stacco sumo', 'Forza', 'Stacchi', 'Intermedio', NULL, ARRAY['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Adduttori', 'Avambracci', 'Glutei', 'Lombari', 'Dorso', 'Quadricipiti', 'Trapezi']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Forza massimale']::text[], '{}'::text[], '{}'::text[]),
-- fed:Romanian_Deadlift · Stacco rumeno
('fed:Romanian_Deadlift', 'Romanian Deadlift', 'Stacco rumeno', 'Forza', 'Stacchi', 'Intermedio', NULL, ARRAY['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.', 'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.', 'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.', 'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei', 'Lombari']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Stiff-Legged_Dumbbell_Deadlift · Stacco a gambe tese con manubri
('fed:Stiff-Legged_Dumbbell_Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'Stacco a gambe tese con manubri', 'Forza', 'Stacchi', 'Principiante', NULL, ARRAY['Grasp a couple of dumbbells holding them by your side at arm''s length.', 'Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.', 'Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement', 'Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Glutei', 'Lombari']::text[], ARRAY['Manubri']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Kettlebell_One-Legged_Deadlift · Stacco rumeno monopodalico con kettlebell
('fed:Kettlebell_One-Legged_Deadlift', 'Kettlebell One-Legged Deadlift', 'Stacco rumeno monopodalico con kettlebell', 'Forza', 'Stacchi', 'Intermedio', NULL, ARRAY['Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.', 'Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.', 'Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Glutei', 'Lombari']::text[], ARRAY['Kettlebell']::text[], 'hinge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Good_Morning · Good morning
('fed:Good_Morning', 'Good Morning', 'Good morning', 'Forza', 'Stacchi', 'Intermedio', NULL, ARRAY['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Addominali', 'Glutei', 'Lombari']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Pull_Through · Pull through al cavo
('fed:Pull_Through', 'Pull Through', 'Pull through al cavo', 'Forza', 'Glutei', 'Principiante', NULL, ARRAY['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.', 'Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Femorali', 'Lombari']::text[], ARRAY['Cavi']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Barbell_Hip_Thrust · Hip thrust con bilanciere
('fed:Barbell_Hip_Thrust', 'Barbell Hip Thrust', 'Hip thrust con bilanciere', 'Forza', 'Glutei', 'Intermedio', NULL, ARRAY['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Polpacci', 'Femorali']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Accelerazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Barbell_Glute_Bridge · Glute bridge con bilanciere
('fed:Barbell_Glute_Bridge', 'Barbell Glute Bridge', 'Glute bridge con bilanciere', 'Forza', 'Glutei', 'Intermedio', NULL, ARRAY['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Polpacci', 'Femorali']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Butt_Lift_Bridge · Ponte glutei
('fed:Butt_Lift_Bridge', 'Butt Lift (Bridge)', 'Ponte glutei', 'Forza', 'Glutei', 'Principiante', NULL, ARRAY['Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.', 'Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.', 'Slowly go back to the starting position as you breathe in.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Femorali']::text[], ARRAY['Corpo libero']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Single_Leg_Glute_Bridge · Ponte glutei monopodalico
('fed:Single_Leg_Glute_Bridge', 'Single Leg Glute Bridge', 'Ponte glutei monopodalico', 'Forza', 'Glutei', 'Principiante', NULL, ARRAY['Lay on the floor with your feet flat and knees bent.', 'Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.', 'Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.', 'Extend as far as possible, pause and then return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Femorali']::text[], ARRAY['Corpo libero']::text[], 'hinge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità', 'Attivazione']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Hyperextensions_Back_Extensions · Iperestensioni lombari (back extension)
('fed:Hyperextensions_Back_Extensions', 'Hyperextensions (Back Extensions)', 'Iperestensioni lombari (back extension)', 'Forza', 'Catena posteriore', 'Principiante', NULL, ARRAY['Lie face down on a hyperextension bench, tucking your ankles securely under the footpads.', 'Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction.', 'With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.', 'Start bending forward slowly at the waist as far as you can while keeping your back flat. Inhale as you perform this movement. Keep moving forward until you feel a nice stretch on the hamstrings and you can no longer keep going without a rounding of the back. Tip: Never round the back as you perform this exercise. Also, some people can go farther than others. The key thing is that you go as far as your body allows you to without rounding the back.', 'Slowly raise your torso back to the initial position as you inhale. Tip: Avoid the temptation to arch your back past a straight line. Also, do not swing the torso at any time in order to protect the back from injury.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Lombari']::text[], ARRAY['Glutei', 'Femorali']::text[], ARRAY['Altro']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Lombari']::text[]),
-- fed:Reverse_Hyperextension · Reverse hyper
('fed:Reverse_Hyperextension', 'Reverse Hyperextension', 'Reverse hyper', 'Forza', 'Catena posteriore', 'Intermedio', NULL, ARRAY['Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.', 'To begin the movement, flex the hips, pulling the legs forward.', 'Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.', 'Return by again flexing the hip, pulling the carriage forward as far as you can.', 'Repeat for the desired number of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei']::text[], ARRAY['Macchina']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Farmers_Walk · Farmer's walk (camminata del contadino)
('fed:Farmers_Walk', 'Farmer''s Walk', 'Farmer''s walk (camminata del contadino)', 'Forza', 'Trasporti', 'Intermedio', NULL, ARRAY['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.', 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.', 'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[], '{}'::text[], '{}'::text[], ARRAY['Avambracci']::text[], ARRAY['Addominali', 'Glutei', 'Femorali', 'Lombari', 'Quadricipiti', 'Trapezi']::text[], ARRAY['Altro']::text[], 'carry', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Sled_Push · Spinta della slitta
('fed:Sled_Push', 'Sled Push', 'Spinta della slitta', 'Potenza', 'Slitta', 'Principiante', NULL, ARRAY['Load your pushing sled with the desired weight.', 'Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Pettorali', 'Glutei', 'Femorali', 'Tricipiti']::text[], ARRAY['Altro']::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Accelerazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Standing_Calf_Raises · Calf raise in piedi
('fed:Standing_Calf_Raises', 'Standing Calf Raises', 'Calf raise in piedi', 'Prevenzione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], ARRAY['Macchina']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Standing_Dumbbell_Calf_Raise · Calf raise in piedi con manubri
('fed:Standing_Dumbbell_Calf_Raise', 'Standing Dumbbell Calf Raise', 'Calf raise in piedi con manubri', 'Prevenzione', 'Caviglia/polpaccio', 'Intermedio', NULL, ARRAY['Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position.', 'With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.', 'As you inhale, go back to the starting position by slowly lowering the heels.', 'Repeat for the recommended amount of times.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], ARRAY['Manubri']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Seated_Calf_Raise · Calf raise da seduto (soleo)
('fed:Seated_Calf_Raise', 'Seated Calf Raise', 'Calf raise da seduto (soleo)', 'Prevenzione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], ARRAY['Macchina']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Dumbbell_Seated_One-Leg_Calf_Raise · Calf raise da seduto monopodalico con manubrio
('fed:Dumbbell_Seated_One-Leg_Calf_Raise', 'Dumbbell Seated One-Leg Calf Raise', 'Calf raise da seduto monopodalico con manubrio', 'Prevenzione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['Place a block on the floor about 12 inches from a flat bench.', 'Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.', 'Now place the ball of your left foot on the block. This will be your starting position.', 'Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.', 'Slowly return to the starting position, stretching as far down as possible.', 'Repeat for your prescribed number of repetitions and then repeat with the right leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], ARRAY['Manubri']::text[], 'isometric', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Rocking_Standing_Calf_Raise · Calf raise in piedi con oscillazione
('fed:Rocking_Standing_Calf_Raise', 'Rocking Standing Calf Raise', 'Calf raise in piedi con oscillazione', 'Prevenzione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck).', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance. Also maintain a straight back and keep the knees with a slight bend; never locked. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending (other than the slight initial bend we created during positioning) at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Now lift your toes by contracting the tibia muscles in the front of the calves as you breathe out.', 'Hold for a second and bring them back down as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], ARRAY['Bilanciere']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Mobilità']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Balance_Board · Tavoletta propriocettiva
('fed:Balance_Board', 'Balance Board', 'Tavoletta propriocettiva', 'Prevenzione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['Place a balance board in front of you.', 'Stand up on it and try to balance yourself.', 'Hold the balance for as long as desired.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], ARRAY['Femorali', 'Quadricipiti']::text[], ARRAY['Altro']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Stabilità', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Caviglia', 'LCA/ginocchio']::text[]),
-- fed:Glute_Ham_Raise · Glute-ham raise (GHD)
('fed:Glute_Ham_Raise', 'Glute Ham Raise', 'Glute-ham raise (GHD)', 'Prevenzione', 'Femorali', 'Intermedio', NULL, ARRAY['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.', 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.', 'Return to the starting position, keeping your descent under control.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei']::text[], ARRAY['Macchina']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Natural_Glute_Ham_Raise · Glute-ham raise naturale
('fed:Natural_Glute_Ham_Raise', 'Natural Glute Ham Raise', 'Glute-ham raise naturale', 'Prevenzione', 'Femorali', 'Intermedio', NULL, ARRAY['Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture.', 'This will be your starting position. Lower yourself under control until your knees are almost completely straight.', 'Remaining in control, raise yourself back up to the starting position.', 'If you are unable to complete a rep, use a band, a partner, or push off of a box to aid in completing a repetition.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei', 'Lombari']::text[], ARRAY['Corpo libero']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Floor_Glute-Ham_Raise · Glute-ham raise a terra
('fed:Floor_Glute-Ham_Raise', 'Floor Glute-Ham Raise', 'Glute-ham raise a terra', 'Prevenzione', 'Femorali', 'Intermedio', NULL, ARRAY['You can use a partner for this exercise or brace your feet under something stable.', 'Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position.', 'Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward.', 'Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to lightly push off the floor to aid your return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei']::text[], '{}'::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Lying_Leg_Curls · Leg curl sdraiato
('fed:Lying_Leg_Curls', 'Lying Leg Curls', 'Leg curl sdraiato', 'Prevenzione', 'Femorali', 'Principiante', NULL, ARRAY['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], '{}'::text[], ARRAY['Macchina']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Seated_Leg_Curl · Leg curl da seduto
('fed:Seated_Leg_Curl', 'Seated Leg Curl', 'Leg curl da seduto', 'Prevenzione', 'Femorali', 'Principiante', NULL, ARRAY['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.', 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.', 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], '{}'::text[], ARRAY['Macchina']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Standing_Leg_Curl · Leg curl in piedi monopodalico
('fed:Standing_Leg_Curl', 'Standing Leg Curl', 'Leg curl in piedi monopodalico', 'Prevenzione', 'Femorali', 'Principiante', NULL, ARRAY['Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.', 'Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.', 'As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.', 'Perform the same exercise now for the left leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], '{}'::text[], ARRAY['Macchina']::text[], 'isometric', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Ball_Leg_Curl · Leg curl su fitball
('fed:Ball_Leg_Curl', 'Ball Leg Curl', 'Leg curl su fitball', 'Prevenzione', 'Femorali', 'Principiante', NULL, ARRAY['Begin on the floor laying on your back with your feet on top of the ball.', 'Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position.', 'Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet.', 'Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings.', 'After a brief pause, return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei']::text[], ARRAY['Fitball']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Stabilità', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Platform_Hamstring_Slides · Hamstring slide (leg curl in scivolamento)
('fed:Platform_Hamstring_Slides', 'Platform Hamstring Slides', 'Hamstring slide (leg curl in scivolamento)', 'Prevenzione', 'Femorali', 'Principiante', NULL, ARRAY['For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position.', 'Begin the movement by flexing the knee, keeping your other leg straight.', 'Continue bringing the heel closer to you, sliding it on the floor.', 'At full knee flexion, reverse the movement to return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Glutei']::text[], ARRAY['Altro']::text[], 'hinge', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Seated_Band_Hamstring_Curl · Leg curl da seduto con elastico
('fed:Seated_Band_Hamstring_Curl', 'Seated Band Hamstring Curl', 'Leg curl da seduto con elastico', 'Prevenzione', 'Femorali', 'Principiante', NULL, ARRAY['Secure a band close to the ground and place a bench a couple feet away from it.', 'Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.', 'Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.', 'Pause at the completion of the movement, and then slowly return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], '{}'::text[], ARRAY['Altro']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Attivazione']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Band_Hip_Adductions · Adduzione dell'anca con elastico
('fed:Band_Hip_Adductions', 'Band Hip Adductions', 'Adduzione dell''anca con elastico', 'Prevenzione', 'Adduttori', 'Principiante', NULL, ARRAY['Anchor a band around a solid post or other object.', 'Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.', 'Stand up straight and hold onto the post if needed. This will be your starting position.', 'Keeping the knee straight, raise your right legs out to the side as far as you can.', 'Return to the starting position and repeat for the desired rep count.', 'Switch sides.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], '{}'::text[], ARRAY['Elastici']::text[], 'isometric', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Pubalgia/adduttori']::text[]),
-- fed:Cable_Hip_Adduction · Adduzione dell'anca al cavo
('fed:Cable_Hip_Adduction', 'Cable Hip Adduction', 'Adduzione dell''anca al cavo', 'Prevenzione', 'Adduttori', 'Principiante', NULL, ARRAY['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.', 'Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.', 'Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.', 'Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.', 'Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], '{}'::text[], ARRAY['Cavi']::text[], 'isometric', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Pubalgia/adduttori']::text[]),
-- fed:Thigh_Adductor · Adductor machine
('fed:Thigh_Adductor', 'Thigh Adductor', 'Adductor machine', 'Prevenzione', 'Adduttori', 'Principiante', NULL, ARRAY['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], ARRAY['Glutei', 'Femorali']::text[], ARRAY['Macchina']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Pubalgia/adduttori']::text[]),
-- fed:Thigh_Abductor · Abductor machine
('fed:Thigh_Abductor', 'Thigh Abductor', 'Abductor machine', 'Prevenzione', 'Abduttori', 'Principiante', NULL, ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Abduttori']::text[], ARRAY['Glutei']::text[], ARRAY['Macchina']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Side_Lying_Groin_Stretch · Allungamento adduttori sul fianco
('fed:Side_Lying_Groin_Stretch', 'Side Lying Groin Stretch', 'Allungamento adduttori sul fianco', 'Mobilità e attivazione', 'Adduttori', 'Principiante', NULL, ARRAY['Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.', 'Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).', 'Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], ARRAY['Femorali']::text[], '{}'::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità']::text[], '{}'::text[], ARRAY['Pubalgia/adduttori']::text[]),
-- fed:Groiners · Groiners
('fed:Groiners', 'Groiners', 'Groiners', 'Mobilità e attivazione', 'Adduttori', 'Intermedio', NULL, ARRAY['Begin in a pushup position on the floor. This will be your starting position.', 'Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so.', 'Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], '{}'::text[], ARRAY['Corpo libero']::text[], 'mobility', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità', 'Attivazione']::text[], '{}'::text[], ARRAY['Pubalgia/adduttori']::text[]),
-- fed:Adductor · Foam roller adduttori
('fed:Adductor', 'Adductor', 'Foam roller adduttori', 'Recupero', 'Automassaggio', 'Intermedio', NULL, ARRAY['Lie face down with one leg on a foam roll.', 'Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.', 'While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], '{}'::text[], ARRAY['Foam roller']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero', 'Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Freehand_Jump_Squat · Squat jump a corpo libero
('fed:Freehand_Jump_Squat', 'Freehand Jump Squat', 'Squat jump a corpo libero', 'Potenza', 'Salti verticali', 'Intermedio', NULL, ARRAY['Cross your arms over your chest.', 'With your head up and your back straight, position your feet at shoulder width.', 'Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.', 'Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.', 'When you touch the floor again, immediately squat down and jump again.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Weighted_Jump_Squat · Squat jump con sovraccarico
('fed:Weighted_Jump_Squat', 'Weighted Jump Squat', 'Squat jump con sovraccarico', 'Potenza', 'Salti verticali', 'Intermedio', NULL, ARRAY['Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise.', 'The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position.', 'Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips, knees, and ankles. Maintain good posture throughout the jump.', 'As you return to the ground, absorb the impact through your legs.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali', 'Lombari']::text[], ARRAY['Bilanciere']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Rocket_Jump · Salto con contromovimento e slancio delle braccia
('fed:Rocket_Jump', 'Rocket Jump', 'Salto con contromovimento e slancio delle braccia', 'Potenza', 'Salti verticali', 'Principiante', NULL, ARRAY['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.', 'To initiate the move, squat down halfway and explode back up as high as possible.', 'Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Star_Jump · Star jump
('fed:Star_Jump', 'Star Jump', 'Star jump', 'Potenza', 'Salti verticali', 'Principiante', NULL, ARRAY['Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.', 'To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.', 'As you land, bring your limbs back in and absorb your impact through the legs.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali', 'Spalle']::text[], ARRAY['Corpo libero']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Front_Box_Jump · Box jump
('fed:Front_Box_Jump', 'Front Box Jump', 'Box jump', 'Potenza', 'Salti verticali', 'Principiante', NULL, ARRAY['Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position.', 'Perform a short squat in preparation for jumping, swinging your arms behind you.', 'Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up.', 'Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably step down one leg at a time.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Glutei', 'Quadricipiti']::text[], ARRAY['Altro']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Box_Jump_Multiple_Response · Box jump ripetuti
('fed:Box_Jump_Multiple_Response', 'Box Jump (Multiple Response)', 'Box jump ripetuti', 'Potenza', 'Salti verticali', 'Principiante', NULL, ARRAY['Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent.', 'Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform.', 'Immediately drop or jump back down to the original starting place; then repeat the sequence.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Glutei', 'Quadricipiti']::text[], ARRAY['Altro']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Standing_Long_Jump · Salto in lungo da fermo (broad jump)
('fed:Standing_Long_Jump', 'Standing Long Jump', 'Salto in lungo da fermo (broad jump)', 'Potenza', 'Salti orizzontali', 'Principiante', NULL, ARRAY['This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart.', 'Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can.', 'Attempt to land with your feet out in front you, reaching as far as possible with your legs.', 'Measure the distance from your landing point to the starting point and track results.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Esplosività', 'Accelerazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Side_Standing_Long_Jump · Salto in lungo laterale da fermo
('fed:Side_Standing_Long_Jump', 'Side Standing Long Jump', 'Salto in lungo laterale da fermo', 'Potenza', 'Salti laterali', 'Principiante', NULL, ARRAY['Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position.', 'Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can.', 'Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], '{}'::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Cambio di direzione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Split_Jump · Split jump (affondo saltato)
('fed:Split_Jump', 'Split Jump', 'Split jump (affondo saltato)', 'Potenza', 'Salti unilaterali', 'Principiante', NULL, ARRAY['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot.', 'Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump, bring your feet together, and move them back to their initial positions as you land.', 'Absorb the impact by reverting back to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'jump', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Scissors_Jump · Scissor jump (affondi saltati alternati)
('fed:Scissors_Jump', 'Scissors Jump', 'Scissor jump (affondi saltati alternati)', 'Potenza', 'Salti unilaterali', 'Principiante', NULL, ARRAY['Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground.', 'Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift.', 'As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front.', 'As you land, absorb the impact through the legs by adopting the lunge position, and repeat.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Glutei', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'jump', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Lateral_Bound · Balzo laterale (lateral bound)
('fed:Lateral_Bound', 'Lateral Bound', 'Balzo laterale (lateral bound)', 'Potenza', 'Salti laterali', 'Principiante', NULL, ARRAY['Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position.', 'Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg.', 'Immediately push off and extend, attempting to bound to the side as far as possible.', 'Upon landing, immediately push off in the opposite direction, returning to your original start position.', 'Continue back and forth for several repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], ARRAY['Abduttori', 'Polpacci', 'Glutei', 'Femorali', 'Quadricipiti']::text[], ARRAY['Corpo libero']::text[], 'jump', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Cambio di direzione', 'Decelerazione']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Alternate_Leg_Diagonal_Bound · Balzi alternati in diagonale (bounding)
('fed:Alternate_Leg_Diagonal_Bound', 'Alternate Leg Diagonal Bound', 'Balzi alternati in diagonale (bounding)', 'Potenza', 'Salti orizzontali', 'Principiante', NULL, ARRAY['Assume a comfortable stance with one foot slightly in front of the other.', 'Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.', 'It may help to use a line on the ground to guage distance from side to side.', 'Repeat the sequence with the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Glutei', 'Femorali']::text[], '{}'::text[], 'jump', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Accelerazione', 'Cambio di direzione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Single-Leg_Hop_Progression · Balzi monopodalici in avanti sui coni
('fed:Single-Leg_Hop_Progression', 'Single-Leg Hop Progression', 'Balzi monopodalici in avanti sui coni', 'Potenza', 'Salti unilaterali', 'Principiante', NULL, ARRAY['Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position.', 'Hop forward, jumping and landing with the same leg over the cone.', 'Use a countermovement jump to hop from cone to cone.', 'At the end, turn around and go back on the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Femorali']::text[], ARRAY['Altro']::text[], 'jump', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Single-Leg_Lateral_Hop · Balzi laterali monopodalici
('fed:Single-Leg_Lateral_Hop', 'Single-Leg Lateral Hop', 'Balzi laterali monopodalici', 'Potenza', 'Salti unilaterali', 'Principiante', NULL, ARRAY['Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent.', 'To begin, execute a counterjump to hop sideways over the cone.', 'Land on your jumping leg, and immediately rebound out of it by jumping back to the start position.', 'Continue hopping back and forth.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Femorali']::text[], ARRAY['Altro']::text[], 'jump', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Cambio di direzione', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio', 'Caviglia']::text[]),
-- fed:One-Arm_Kettlebell_Swings · Swing monobraccio con kettlebell
('fed:One-Arm_Kettlebell_Swings', 'One-Arm Kettlebell Swings', 'Swing monobraccio con kettlebell', 'Potenza', 'Hinge balistico', 'Intermedio', NULL, '{}'::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei', 'Lombari', 'Spalle']::text[], ARRAY['Kettlebell']::text[], 'hinge', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Power_Clean · Girata al petto (power clean)
('fed:Power_Clean', 'Power Clean', 'Girata al petto (power clean)', 'Potenza', 'Sollevamenti olimpici', 'Intermedio', NULL, ARRAY['Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.', 'Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.', 'Place the bar about 1 inch in front of your shins and over the balls of your feet.', 'Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.', 'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.', 'Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.', 'Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.', 'As the bar raises keep it as close to the shins as possible.', 'As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.', 'Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.', 'Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.', 'Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.', 'When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.', 'As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.', 'Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.', 'After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.', 'Simultaneously, flex the hips and knees into a quarter squat position.', 'Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.', 'Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.', 'Stand up by extending the hips and knees to a fully erect position.', 'Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.', 'Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.', 'Squat down with the elbows fully extended until the bar touches the floor.', 'Start over at Phase 1 and repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Avambracci', 'Glutei', 'Lombari', 'Dorso', 'Quadricipiti', 'Spalle', 'Trapezi', 'Tricipiti']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Hang_Clean · Girata dall'appeso (hang clean)
('fed:Hang_Clean', 'Hang Clean', 'Girata dall''appeso (hang clean)', 'Potenza', 'Sollevamenti olimpici', 'Intermedio', NULL, ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Avambracci', 'Glutei', 'Femorali', 'Lombari', 'Spalle', 'Trapezi']::text[], ARRAY['Bilanciere']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Medicine_Ball_Scoop_Throw · Lancio della palla medica dal basso
('fed:Medicine_Ball_Scoop_Throw', 'Medicine Ball Scoop Throw', 'Lancio della palla medica dal basso', 'Potenza', 'Lanci con palla medica', 'Principiante', NULL, ARRAY['Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet.', 'Begin by thrusting the hips forward as you extend through the legs, jumping up.', 'As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], ARRAY['Addominali', 'Femorali', 'Quadricipiti']::text[], ARRAY['Palla medica']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Backward_Medicine_Ball_Throw · Lancio all'indietro della palla medica
('fed:Backward_Medicine_Ball_Throw', 'Backward Medicine Ball Throw', 'Lancio all''indietro della palla medica', 'Potenza', 'Lanci con palla medica', 'Principiante', NULL, ARRAY['This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall.', 'Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs.', 'Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner.', 'Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], '{}'::text[], ARRAY['Palla medica']::text[], 'hinge', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Overhead_Slam · Slam della palla medica
('fed:Overhead_Slam', 'Overhead Slam', 'Slam della palla medica', 'Potenza', 'Lanci con palla medica', 'Principiante', NULL, ARRAY['Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position.', 'Initiate the countermovement by raising the ball above your head and fully extending your body.', 'Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can.', 'Receive the ball with both hands on the bounce and repeat the movement.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorsali']::text[], '{}'::text[], ARRAY['Palla medica']::text[], 'rotation', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Knee_Tuck_Jump · Tuck jump (salto raccolto)
('fed:Knee_Tuck_Jump', 'Knee Tuck Jump', 'Tuck jump (salto raccolto)', 'Pliometria', 'Rimbalzi', 'Principiante', NULL, ARRAY['Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position.', 'Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands.', 'Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the knees to rebend.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Glutei', 'Quadricipiti']::text[], ARRAY['Corpo libero']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Esplosività', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Hurdle_Hops · Salti sugli ostacolini
('fed:Hurdle_Hops', 'Hurdle Hops', 'Salti sugli ostacolini', 'Pliometria', 'Rimbalzi', 'Principiante', NULL, ARRAY['Set up a row of hurdles or other small barriers, placing them a few feet apart.', 'Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position.', 'Begin by jumping with both feet over the first hurdle, swinging both arms as you jump.', 'Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Glutei']::text[], ARRAY['Altro']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Esplosività', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Front_Cone_Hops_or_hurdle_hops · Salti frontali sui coni
('fed:Front_Cone_Hops_or_hurdle_hops', 'Front Cone Hops (or hurdle hops)', 'Salti frontali sui coni', 'Pliometria', 'Rimbalzi', 'Principiante', NULL, ARRAY['Set up a row of cones or other small barriers, placing them a few feet apart.', 'Stand in front of the first cone with your feet shoulder width apart. This will be your starting position.', 'Begin by jumping with both feet over the first cone, swinging both arms as you jump.', 'Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone.', 'Continue until you have jumped over all of the cones.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Altro']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Esplosività', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Lateral_Cone_Hops · Salti laterali sui coni
('fed:Lateral_Cone_Hops', 'Lateral Cone Hops', 'Salti laterali sui coni', 'Pliometria', 'Rimbalzi laterali', 'Principiante', NULL, ARRAY['Position a number of cones in a row several feet apart.', 'Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position.', 'Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone.', 'Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], ARRAY['Abduttori', 'Polpacci', 'Glutei', 'Femorali', 'Quadricipiti']::text[], ARRAY['Altro']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Esplosività', 'Cambio di direzione']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Lateral_Box_Jump · Salto laterale sul box
('fed:Lateral_Box_Jump', 'Lateral Box Jump', 'Salto laterale sul box', 'Pliometria', 'Rimbalzi laterali', 'Principiante', NULL, ARRAY['Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position.', 'Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side.', 'Bring your knees high enough to ensure your feet have good clearance over the box.', 'Land on the center of the box, using your legs to absorb the impact.', 'Carefully jump down to the other side of the box, and continue going back and forth for several repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], ARRAY['Abduttori', 'Polpacci', 'Glutei', 'Femorali', 'Quadricipiti']::text[], ARRAY['Altro']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Esplosività', 'Cambio di direzione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Side_to_Side_Box_Shuffle · Box shuffle laterale
('fed:Side_to_Side_Box_Shuffle', 'Side to Side Box Shuffle', 'Box shuffle laterale', 'Pliometria', 'Rimbalzi laterali', 'Principiante', NULL, ARRAY['Stand to one side of the box with your left foot resting on the middle of it.', 'To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement.', 'Continue shuffling back and forth across the box.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Femorali']::text[], ARRAY['Altro']::text[], 'jump', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Esplosività', 'Agilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Linear_Depth_Jump · Depth jump
('fed:Linear_Depth_Jump', 'Linear Depth Jump', 'Depth jump', 'Pliometria', 'Pliometria intensiva', 'Intermedio', NULL, ARRAY['You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform.', 'To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex.', 'Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform.', 'Land softly, asborbing the impact through the legs.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Altro']::text[], 'jump', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Esplosività', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Linear_3-Part_Start_Technique · Tecnica di partenza in 3 tempi
('fed:Linear_3-Part_Start_Technique', 'Linear 3-Part Start Technique', 'Tecnica di partenza in 3 tempi', 'Velocità e agilità', 'Accelerazione', 'Principiante', NULL, ARRAY['This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left.', 'Place your right hand onto the line, and thing bring your nose close to your left knee.', 'Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting position.', 'Take your left hand up so that it is parallel to the ground, pointing behind you, and explode out when ready.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Quadricipiti']::text[], '{}'::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Velocità', 'Accelerazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Linear_Acceleration_Wall_Drill · Wall drill di accelerazione
('fed:Linear_Acceleration_Wall_Drill', 'Linear Acceleration Wall Drill', 'Wall drill di accelerazione', 'Velocità e agilità', 'Accelerazione', 'Principiante', NULL, ARRAY['Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted.', 'Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground.', 'Switch legs, raising the opposite knee, and then attacking the ground straight down.', 'Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei', 'Quadricipiti']::text[], '{}'::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Accelerazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Sled_Drag_-_Harness · Traino della slitta con imbragatura
('fed:Sled_Drag_-_Harness', 'Sled Drag - Harness', 'Traino della slitta con imbragatura', 'Velocità e agilità', 'Sprint resistiti', 'Principiante', NULL, ARRAY['To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt.', 'Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Altro']::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Accelerazione', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Prowler_Sprint · Sprint con prowler
('fed:Prowler_Sprint', 'Prowler Sprint', 'Sprint con prowler', 'Velocità e agilità', 'Sprint resistiti', 'Principiante', NULL, ARRAY['Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down.', 'You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement.', 'With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Pettorali', 'Glutei', 'Quadricipiti', 'Spalle']::text[], ARRAY['Altro']::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Accelerazione', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Fast_Skipping · Skip veloce
('fed:Fast_Skipping', 'Fast Skipping', 'Skip veloce', 'Velocità e agilità', 'Tecnica di corsa', 'Principiante', NULL, ARRAY['Start in a relaxed position with one leg slightly forward. This will be your starting position.', 'Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.', 'Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Velocità', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Moving_Claw_Series · Calciata dietro in corsa (claw drill)
('fed:Moving_Claw_Series', 'Moving Claw Series', 'Calciata dietro in corsa (claw drill)', 'Velocità e agilità', 'Tecnica di corsa', 'Principiante', NULL, ARRAY['This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends.', 'Reload the quad as the leg moves back forward, attacking the ground on the next step.', 'Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Quadricipiti']::text[], '{}'::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Velocità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Single_Leg_Butt_Kick · Calciata ai glutei monopodalica
('fed:Single_Leg_Butt_Kick', 'Single Leg Butt Kick', 'Calciata ai glutei monopodalica', 'Velocità e agilità', 'Tecnica di corsa', 'Principiante', NULL, ARRAY['Begin by standing on one leg, with the bent knee raised. This will be your start position.', 'Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.', 'Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.', 'Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Femorali']::text[], ARRAY['Corpo libero']::text[], 'jump', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Velocità', 'Esplosività']::text[], '{}'::text[], '{}'::text[]),
-- fed:Bench_Sprint · Bench sprint (cambi rapidi sul rialzo)
('fed:Bench_Sprint', 'Bench Sprint', 'Bench sprint (cambi rapidi sul rialzo)', 'Velocità e agilità', 'Frequenza', 'Principiante', NULL, ARRAY['Stand on the ground with one foot resting on a bench or box with your heel close to the edge.', 'Push off with your foot on top of the bench, extending through the hip and knee.', 'Land with the opposite foot on top of the box, returning your other foot back to the start position.', 'Continue alternating from one foot to another to complete the set.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Altro']::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Velocità', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Carioca_Quick_Step · Passo incrociato rapido (carioca)
('fed:Carioca_Quick_Step', 'Carioca Quick Step', 'Passo incrociato rapido (carioca)', 'Velocità e agilità', 'Agilità laterale', 'Principiante', NULL, ARRAY['Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.', 'With your right foot, quick step behind and pull the knee up.', 'Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], ARRAY['Addominali', 'Abduttori', 'Polpacci', 'Glutei', 'Femorali', 'Quadricipiti']::text[], '{}'::text[], 'cod', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Agilità', 'Cambio di direzione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Side_Hop-Sprint · Salti laterali + sprint
('fed:Side_Hop-Sprint', 'Side Hop-Sprint', 'Salti laterali + sprint', 'Velocità e agilità', 'Reattività', 'Principiante', NULL, ARRAY['Stand to the side of a cone or hurdle.', 'Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started.', 'Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Abduttori', 'Adduttori', 'Polpacci', 'Femorali']::text[], ARRAY['Altro']::text[], 'cod', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Agilità', 'Accelerazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Single-Cone_Sprint_Drill · Sprint attorno al cono
('fed:Single-Cone_Sprint_Drill', 'Single-Cone Sprint Drill', 'Sprint attorno al cono', 'Velocità e agilità', 'Cambio di direzione', 'Principiante', NULL, ARRAY['This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward.', 'Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action.', 'Rest after three trips around the cone.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Altro']::text[], 'cod', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Agilità', 'Cambio di direzione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Plank · Plank
('fed:Plank', 'Plank', 'Plank', 'Core', 'Anti-estensione', 'Principiante', NULL, ARRAY['Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.', 'Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], '{}'::text[], ARRAY['Corpo libero']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Side_Bridge · Plank laterale (side plank)
('fed:Side_Bridge', 'Side Bridge', 'Plank laterale (side plank)', 'Core', 'Anti-flessione laterale', 'Principiante', NULL, '{}'::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Spalle']::text[], ARRAY['Corpo libero']::text[], 'isometric', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Push_Up_to_Side_Plank · Piegamento + plank laterale
('fed:Push_Up_to_Side_Plank', 'Push Up to Side Plank', 'Piegamento + plank laterale', 'Core', 'Anti-flessione laterale', 'Principiante', NULL, ARRAY['Get into pushup position on the toes with your hands just outside of shoulder width.', 'Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.', 'Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.', 'Lower the arm back to the floor for another pushup and then twist to the other side.', 'Repeat the series, alternating each side, for 10 or more reps.']::text[], '{}'::text[], '{}'::text[], ARRAY['Pettorali']::text[], ARRAY['Addominali', 'Spalle', 'Tricipiti']::text[], ARRAY['Corpo libero']::text[], 'isometric', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Stabilità', 'Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Dead_Bug · Dead bug
('fed:Dead_Bug', 'Dead Bug', 'Dead bug', 'Core', 'Anti-estensione', 'Principiante', NULL, ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.', 'Bring your feet, knees, and hips up to 90 degrees.', 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.', 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.', 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.', 'Stay tight and return the working leg to the starting position.', 'Repeat on the opposite side, alternating until the set is complete.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], '{}'::text[], ARRAY['Corpo libero']::text[], 'isometric', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Stabilità', 'Attivazione']::text[], '{}'::text[], ARRAY['Lombari']::text[]),
-- fed:Pallof_Press · Pallof press
('fed:Pallof_Press', 'Pallof Press', 'Pallof press', 'Core', 'Anti-rotazione', 'Principiante', NULL, ARRAY['Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.', 'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.', 'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.', 'Hold the repetition for several seconds before returning to the starting position.', 'At the conclusion of the set, repeat facing the other direction.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Pettorali', 'Spalle', 'Tricipiti']::text[], ARRAY['Cavi']::text[], 'anti-rotation', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Pallof_Press_With_Rotation · Pallof press con rotazione
('fed:Pallof_Press_With_Rotation', 'Pallof Press With Rotation', 'Pallof press con rotazione', 'Core', 'Rotazione', 'Principiante', NULL, ARRAY['Connect a standard handle to a tower, and position the cable to shoulder height.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.', 'With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.', 'Facing forward, press the cable away from your chest. You core should be tight and engaged.', 'Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.', 'Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.', 'With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Pettorali', 'Spalle', 'Tricipiti']::text[], ARRAY['Cavi']::text[], 'rotation', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Stabilità', 'Potenza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Standing_Cable_Wood_Chop · Wood chop al cavo
('fed:Standing_Cable_Wood_Chop', 'Standing Cable Wood Chop', 'Wood chop al cavo', 'Core', 'Rotazione', 'Principiante', NULL, ARRAY['Connect a standard handle to a tower, and move the cable to the highest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle down and across your body to your front knee while rotating your torso.', 'Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.', 'Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Spalle']::text[], ARRAY['Cavi']::text[], 'rotation', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Potenza', 'Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Standing_Cable_Lift · Cable lift (dal basso in alto)
('fed:Standing_Cable_Lift', 'Standing Cable Lift', 'Cable lift (dal basso in alto)', 'Core', 'Rotazione', 'Principiante', NULL, ARRAY['Connect a standard handle on a tower, and move the cable to the lowest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.', 'Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.', 'Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Spalle']::text[], ARRAY['Cavi']::text[], 'rotation', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Russian_Twist · Russian twist
('fed:Russian_Twist', 'Russian Twist', 'Russian twist', 'Core', 'Rotazione', 'Intermedio', NULL, ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.', 'Twist your torso to the right side until your arms are parallel with the floor while breathing out.', 'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Lombari']::text[], ARRAY['Corpo libero']::text[], 'rotation', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Landmine_180s · Landmine 180
('fed:Landmine_180s', 'Landmine 180''s', 'Landmine 180', 'Core', 'Rotazione', 'Principiante', NULL, ARRAY['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.', 'Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.', 'Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.', 'Reverse the motion to swing the weight all the way to the opposite side.', 'Continue alternating the movement until the set is complete.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Glutei', 'Lombari', 'Spalle']::text[], ARRAY['Bilanciere']::text[], 'rotation', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Potenza', 'Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Hanging_Leg_Raise · Leg raise alla sbarra
('fed:Hanging_Leg_Raise', 'Hanging Leg Raise', 'Leg raise alla sbarra', 'Core', 'Flessione', 'Avanzato', NULL, ARRAY['Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.', 'Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.', 'Go back slowly to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], '{}'::text[], ARRAY['Corpo libero']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Wind_Sprints · Knee raise alternati alla sbarra
('fed:Wind_Sprints', 'Wind Sprints', 'Knee raise alternati alla sbarra', 'Core', 'Flessione', 'Principiante', NULL, ARRAY['Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.', 'Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3', 'Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.', 'Continue alternating between legs until the set is complete.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], '{}'::text[], ARRAY['Corpo libero']::text[], 'isometric', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Ab_Roller · Ab wheel (ruota addominale)
('fed:Ab_Roller', 'Ab Roller', 'Ab wheel (ruota addominale)', 'Core', 'Anti-estensione', 'Intermedio', NULL, ARRAY['Hold the Ab Roller with both hands and kneel on the floor.', 'Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], ARRAY['Spalle']::text[], ARRAY['Altro']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Stabilità', 'Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Exercise_Ball_Pull-In · Pull-in sulla fitball
('fed:Exercise_Ball_Pull-In', 'Exercise Ball Pull-In', 'Pull-in sulla fitball', 'Core', 'Anti-estensione', 'Principiante', NULL, ARRAY['Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position.', 'Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position.', 'While keeping your back completely straight and the upper body stationary, pull your knees in towards your chest as you exhale, allowing the ball to roll forward under your ankles. Squeeze your abs and hold that position for a second.', 'Now slowly straighten your legs, rolling the ball back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Addominali']::text[], '{}'::text[], ARRAY['Fitball']::text[], 'isometric', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Mountain_Climbers · Mountain climber
('fed:Mountain_Climbers', 'Mountain Climbers', 'Mountain climber', 'Core', 'Dinamico', 'Principiante', NULL, ARRAY['Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.', 'Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Pettorali', 'Femorali', 'Spalle']::text[], '{}'::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Stabilità', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Barbell_Bench_Press_-_Medium_Grip · Panca piana con bilanciere
('fed:Barbell_Bench_Press_-_Medium_Grip', 'Barbell Bench Press - Medium Grip', 'Panca piana con bilanciere', 'Parte superiore', 'Spinta orizzontale', 'Principiante', NULL, ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], '{}'::text[], '{}'::text[], ARRAY['Pettorali']::text[], ARRAY['Spalle', 'Tricipiti']::text[], ARRAY['Bilanciere']::text[], 'push', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Forza massimale']::text[], '{}'::text[], '{}'::text[]),
-- fed:Dumbbell_Bench_Press · Panca piana con manubri
('fed:Dumbbell_Bench_Press', 'Dumbbell Bench Press', 'Panca piana con manubri', 'Parte superiore', 'Spinta orizzontale', 'Principiante', NULL, ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], '{}'::text[], '{}'::text[], ARRAY['Pettorali']::text[], ARRAY['Spalle', 'Tricipiti']::text[], ARRAY['Manubri']::text[], 'push', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Incline_Dumbbell_Press · Panca inclinata con manubri
('fed:Incline_Dumbbell_Press', 'Incline Dumbbell Press', 'Panca inclinata con manubri', 'Parte superiore', 'Spinta orizzontale', 'Principiante', NULL, ARRAY['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.']::text[], '{}'::text[], '{}'::text[], ARRAY['Pettorali']::text[], ARRAY['Spalle', 'Tricipiti']::text[], ARRAY['Manubri']::text[], 'push', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Pushups · Piegamenti sulle braccia (push up)
('fed:Pushups', 'Pushups', 'Piegamenti sulle braccia (push up)', 'Parte superiore', 'Spinta orizzontale', 'Principiante', NULL, ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], '{}'::text[], '{}'::text[], ARRAY['Pettorali']::text[], ARRAY['Spalle', 'Tricipiti']::text[], ARRAY['Corpo libero']::text[], 'push', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Stabilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Standing_Military_Press · Military press in piedi
('fed:Standing_Military_Press', 'Standing Military Press', 'Military press in piedi', 'Parte superiore', 'Spinta verticale', 'Principiante', NULL, ARRAY['Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.', 'Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.', 'Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the collarbone slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], ARRAY['Tricipiti']::text[], ARRAY['Bilanciere']::text[], 'push', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Dumbbell_Shoulder_Press · Shoulder press con manubri
('fed:Dumbbell_Shoulder_Press', 'Dumbbell Shoulder Press', 'Shoulder press con manubri', 'Parte superiore', 'Spinta verticale', 'Intermedio', NULL, ARRAY['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], ARRAY['Tricipiti']::text[], ARRAY['Manubri']::text[], 'push', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Side_Lateral_Raise · Alzate laterali
('fed:Side_Lateral_Raise', 'Side Lateral Raise', 'Alzate laterali', 'Parte superiore', 'Spalle', 'Principiante', NULL, ARRAY['Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.', 'While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.', 'Lower the dumbbells back down slowly to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], '{}'::text[], ARRAY['Manubri']::text[], 'push', 'bilaterale', 'free-exercise-db', 'Unlicense', 1, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Pullups · Trazioni alla sbarra (pull up)
('fed:Pullups', 'Pullups', 'Trazioni alla sbarra (pull up)', 'Parte superiore', 'Tirata verticale', 'Principiante', NULL, ARRAY['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorsali']::text[], ARRAY['Bicipiti', 'Dorso']::text[], ARRAY['Corpo libero']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Chin-Up · Trazioni presa supina (chin up)
('fed:Chin-Up', 'Chin-Up', 'Trazioni presa supina (chin up)', 'Parte superiore', 'Tirata verticale', 'Principiante', NULL, ARRAY['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorsali']::text[], ARRAY['Bicipiti', 'Avambracci', 'Dorso']::text[], ARRAY['Corpo libero']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Band_Assisted_Pull-Up · Trazioni assistite con elastico
('fed:Band_Assisted_Pull-Up', 'Band Assisted Pull-Up', 'Trazioni assistite con elastico', 'Parte superiore', 'Tirata verticale', 'Principiante', NULL, ARRAY['Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.', 'Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position.', 'Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.', 'After a brief pause, return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorsali']::text[], ARRAY['Addominali', 'Avambracci', 'Dorso']::text[], ARRAY['Altro']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Wide-Grip_Lat_Pulldown · Lat machine presa larga
('fed:Wide-Grip_Lat_Pulldown', 'Wide-Grip Lat Pulldown', 'Lat machine presa larga', 'Parte superiore', 'Tirata verticale', 'Principiante', NULL, ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorsali']::text[], ARRAY['Bicipiti', 'Dorso', 'Spalle']::text[], ARRAY['Cavi']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Seated_Cable_Rows · Pulley basso (rematore al cavo)
('fed:Seated_Cable_Rows', 'Seated Cable Rows', 'Pulley basso (rematore al cavo)', 'Parte superiore', 'Tirata orizzontale', 'Principiante', NULL, ARRAY['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorso']::text[], ARRAY['Bicipiti', 'Dorsali', 'Spalle']::text[], ARRAY['Cavi']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:One-Arm_Dumbbell_Row · Rematore con manubrio a un braccio
('fed:One-Arm_Dumbbell_Row', 'One-Arm Dumbbell Row', 'Rematore con manubrio a un braccio', 'Parte superiore', 'Tirata orizzontale', 'Principiante', NULL, ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.', 'Repeat the movement for the specified amount of repetitions.', 'Switch sides and repeat again with the other arm.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorso']::text[], ARRAY['Bicipiti', 'Dorsali', 'Spalle']::text[], ARRAY['Manubri']::text[], 'pull', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Bent_Over_Barbell_Row · Rematore con bilanciere
('fed:Bent_Over_Barbell_Row', 'Bent Over Barbell Row', 'Rematore con bilanciere', 'Parte superiore', 'Tirata orizzontale', 'Principiante', NULL, ARRAY['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorso']::text[], ARRAY['Bicipiti', 'Dorsali', 'Spalle']::text[], ARRAY['Bilanciere']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Inverted_Row · Rematore inverso
('fed:Inverted_Row', 'Inverted Row', 'Rematore inverso', 'Parte superiore', 'Tirata orizzontale', 'Principiante', NULL, ARRAY['Position a bar in a rack to about waist height. You can also use a smith machine.', 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorso']::text[], ARRAY['Dorsali']::text[], '{}'::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Suspended_Row · Rematore in sospensione (TRX)
('fed:Suspended_Row', 'Suspended Row', 'Rematore in sospensione (TRX)', 'Parte superiore', 'Tirata orizzontale', 'Principiante', NULL, ARRAY['Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position.', 'Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so.', 'At the completion of the motion pause, and then return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Dorso']::text[], ARRAY['Bicipiti', 'Dorsali']::text[], ARRAY['Altro']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza']::text[], '{}'::text[], '{}'::text[]),
-- fed:Face_Pull · Face pull
('fed:Face_Pull', 'Face Pull', 'Face pull', 'Parte superiore', 'Spalle', 'Intermedio', NULL, ARRAY['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], ARRAY['Dorso']::text[], ARRAY['Cavi']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Spalla']::text[]),
-- fed:Band_Pull_Apart · Band pull apart
('fed:Band_Pull_Apart', 'Band Pull Apart', 'Band pull apart', 'Parte superiore', 'Spalle', 'Principiante', NULL, ARRAY['Begin with your arms extended straight out in front of you, holding the band with both hands.', 'Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.', 'Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.', 'Pause as you complete the movement, returning to the starting position under control.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], ARRAY['Dorso', 'Trapezi']::text[], ARRAY['Elastici']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Attivazione', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Spalla']::text[]),
-- fed:External_Rotation_with_Band · Extrarotazione della spalla con elastico
('fed:External_Rotation_with_Band', 'External Rotation with Band', 'Extrarotazione della spalla con elastico', 'Parte superiore', 'Spalle', 'Principiante', NULL, ARRAY['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Spalle']::text[], '{}'::text[], ARRAY['Elastici']::text[], 'rotation', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Attivazione', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Spalla']::text[]),
-- fed:Worlds_Greatest_Stretch · World's greatest stretch
('fed:Worlds_Greatest_Stretch', 'World''s Greatest Stretch', 'World''s greatest stretch', 'Mobilità e attivazione', 'Mobilità globale', 'Intermedio', NULL, ARRAY['This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds.', 'Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the stretch.', 'After 10-20 seconds, place your hands on either side of your front foot. Raise the toes of the front foot off of the ground, and straighten your leg. You may need to reposition your rear leg to do so. Hold for 10-20 seconds, and then repeat the entire sequence for the other side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci', 'Glutei', 'Quadricipiti']::text[], '{}'::text[], 'mobility', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Mobilità', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Inchworm · Inchworm (bruco)
('fed:Inchworm', 'Inchworm', 'Inchworm (bruco)', 'Mobilità e attivazione', 'Mobilità globale', 'Principiante', NULL, ARRAY['Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.', 'Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.', 'Keep going until your body is parallel to the ground in a pushup position.', 'Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.', 'Continue walking until your feet are by hour hands, keeping your legs straight as you do so.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], '{}'::text[], ARRAY['Corpo libero']::text[], 'mobility', 'bilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Mobilità', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Kneeling_Hip_Flexor · Allungamento flessori dell'anca in ginocchio
('fed:Kneeling_Hip_Flexor', 'Kneeling Hip Flexor', 'Allungamento flessori dell''anca in ginocchio', 'Mobilità e attivazione', 'Flessori dell''anca', 'Principiante', NULL, ARRAY['Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.', 'Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], '{}'::text[], '{}'::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Intermediate_Hip_Flexor_and_Quad_Stretch · Allungamento flessori dell'anca e quadricipite con cinghia
('fed:Intermediate_Hip_Flexor_and_Quad_Stretch', 'Intermediate Hip Flexor and Quad Stretch', 'Allungamento flessori dell''anca e quadricipite con cinghia', 'Mobilità e attivazione', 'Flessori dell''anca', 'Intermedio', NULL, ARRAY['Lie face down on the floor, with a rope, belt, or band looped around one foot.', 'Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], '{}'::text[], ARRAY['Altro']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Quad_Stretch · Allungamento quadricipite sul fianco
('fed:Quad_Stretch', 'Quad Stretch', 'Allungamento quadricipite sul fianco', 'Mobilità e attivazione', 'Quadricipiti', 'Intermedio', NULL, ARRAY['Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position.', 'With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], '{}'::text[], ARRAY['Altro']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Hamstring_Stretch · Allungamento femorali
('fed:Hamstring_Stretch', 'Hamstring Stretch', 'Allungamento femorali', 'Mobilità e attivazione', 'Femorali', 'Principiante', NULL, ARRAY['Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.', 'Loop a belt, band, or rope over the ball of your foot. This will be your starting position.', 'Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], '{}'::text[], '{}'::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Mobilità']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:90_90_Hamstring · Allungamento femorali 90/90
('fed:90_90_Hamstring', '90/90 Hamstring', 'Allungamento femorali 90/90', 'Mobilità e attivazione', 'Femorali', 'Principiante', NULL, ARRAY['Lie on your back, with one leg extended straight out.', 'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.', 'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.', 'Repeat for 10-20 repetitions, and then switch to the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci']::text[], ARRAY['Corpo libero']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- fed:Runners_Stretch · Runner's stretch
('fed:Runners_Stretch', 'Runner''s Stretch', 'Runner''s stretch', 'Mobilità e attivazione', 'Femorali', 'Principiante', NULL, ARRAY['It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.', 'Keep the front heel on the floor (if it lifts up, scoot your other leg further back).', 'Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Polpacci']::text[], '{}'::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Calf_Stretch_Hands_Against_Wall · Allungamento polpaccio al muro
('fed:Calf_Stretch_Hands_Against_Wall', 'Calf Stretch Hands Against Wall', 'Allungamento polpaccio al muro', 'Mobilità e attivazione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.', 'Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.', 'Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], '{}'::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Mobilità']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Standing_Soleus_And_Achilles_Stretch · Allungamento soleo e tendine d'Achille
('fed:Standing_Soleus_And_Achilles_Stretch', 'Standing Soleus And Achilles Stretch', 'Allungamento soleo e tendine d''Achille', 'Mobilità e attivazione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['Stand with your feet hip-distance apart, one foot slightly in front of the other.', 'Bend both knees, keeping your back heel on the floor. Switch sides.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], '{}'::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Mobilità']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Ankle_Circles · Circonduzioni della caviglia
('fed:Ankle_Circles', 'Ankle Circles', 'Circonduzioni della caviglia', 'Mobilità e attivazione', 'Caviglia/polpaccio', 'Principiante', NULL, ARRAY['Use a sturdy object like a squat rack to hold yourself.', 'Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.', 'When you are done with the right foot, then repeat with the left leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], '{}'::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità', 'Attivazione']::text[], '{}'::text[], ARRAY['Caviglia']::text[]),
-- fed:Hip_Circles_prone · Circonduzioni dell'anca in quadrupedia
('fed:Hip_Circles_prone', 'Hip Circles (prone)', 'Circonduzioni dell''anca in quadrupedia', 'Mobilità e attivazione', 'Anche', 'Principiante', NULL, ARRAY['Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.', 'Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.', 'Perform this slowly for a number of repetitions, and repeat on the other side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Abduttori']::text[], ARRAY['Adduttori']::text[], ARRAY['Corpo libero']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Mobilità', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Standing_Hip_Circles · Circonduzioni dell'anca in piedi
('fed:Standing_Hip_Circles', 'Standing Hip Circles', 'Circonduzioni dell''anca in piedi', 'Mobilità e attivazione', 'Anche', 'Principiante', NULL, ARRAY['Begin standing on one leg, holding to a vertical support.', 'Raise the unsupported knee to 90 degrees. This will be your starting position.', 'Open the hip as far as possible, attempting to make a big circle with your knee.', 'Perform this movement slowly for a number of repetitions, and repeat on the other side.']::text[], '{}'::text[], '{}'::text[], ARRAY['Abduttori']::text[], ARRAY['Adduttori']::text[], ARRAY['Corpo libero']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 3, ARRAY['Mobilità', 'Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Monster_Walk · Monster walk con elastico
('fed:Monster_Walk', 'Monster Walk', 'Monster walk con elastico', 'Mobilità e attivazione', 'Attivazione glutei', 'Principiante', NULL, ARRAY['Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.', 'To begin, take short steps forward alternating your left and right foot.', 'After several steps, do just the opposite and walk backward to where you started.']::text[], '{}'::text[], '{}'::text[], ARRAY['Abduttori']::text[], '{}'::text[], ARRAY['Elastici']::text[], 'isometric', 'alternato', 'free-exercise-db', 'Unlicense', 3, ARRAY['Attivazione', 'Stabilità']::text[], '{}'::text[], ARRAY['LCA/ginocchio']::text[]),
-- fed:Glute_Kickback · Glute kickback in quadrupedia
('fed:Glute_Kickback', 'Glute Kickback', 'Glute kickback in quadrupedia', 'Mobilità e attivazione', 'Attivazione glutei', 'Principiante', NULL, ARRAY['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.', 'Go back to the initial position as you inhale and now repeat with the left leg.', 'Continue to alternate legs until all of the recommended repetitions have been performed.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Femorali']::text[], ARRAY['Corpo libero']::text[], 'hinge', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Hip_Extension_with_Bands · Estensione dell'anca con elastico
('fed:Hip_Extension_with_Bands', 'Hip Extension with Bands', 'Estensione dell''anca con elastico', 'Mobilità e attivazione', 'Attivazione glutei', 'Principiante', NULL, ARRAY['Secure one end of the band to the lower portion of a post and attach the other to one ankle.', 'Facing the attachment point of the band, hold on to the column to stabilize yourself.', 'Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.', 'Return the leg to the starting position.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], ARRAY['Femorali']::text[], ARRAY['Elastici']::text[], 'hinge', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Attivazione']::text[], '{}'::text[], '{}'::text[]),
-- fed:Bicycling_Stationary · Cyclette
('fed:Bicycling_Stationary', 'Bicycling, Stationary', 'Cyclette', 'Recupero', 'Cardio a bassa intensità', 'Principiante', NULL, ARRAY['To begin, seat yourself on the bike and adjust the seat to your height.', 'Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Macchina']::text[], 'mobility', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero']::text[], '{}'::text[], '{}'::text[]),
-- fed:Walking_Treadmill · Camminata su tapis roulant
('fed:Walking_Treadmill', 'Walking, Treadmill', 'Camminata su tapis roulant', 'Recupero', 'Cardio a bassa intensità', 'Principiante', NULL, ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn''t burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Macchina']::text[], 'mobility', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero']::text[], '{}'::text[], '{}'::text[]),
-- fed:Jogging_Treadmill · Corsa lenta su tapis roulant
('fed:Jogging_Treadmill', 'Jogging, Treadmill', 'Corsa lenta su tapis roulant', 'Recupero', 'Cardio a bassa intensità', 'Principiante', NULL, ARRAY['To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Glutei', 'Femorali']::text[], ARRAY['Macchina']::text[], 'sprint', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero']::text[], '{}'::text[], '{}'::text[]),
-- fed:Elliptical_Trainer · Ellittica
('fed:Elliptical_Trainer', 'Elliptical Trainer', 'Ellittica', 'Recupero', 'Cardio a bassa intensità', 'Intermedio', NULL, ARRAY['To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.', 'The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Polpacci', 'Glutei', 'Femorali']::text[], ARRAY['Macchina']::text[], 'mobility', 'alternato', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero']::text[], '{}'::text[], '{}'::text[]),
-- fed:Rowing_Stationary · Vogatore
('fed:Rowing_Stationary', 'Rowing, Stationary', 'Vogatore', 'Recupero', 'Cardio a bassa intensità', 'Intermedio', NULL, ARRAY['To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.', 'There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.', 'The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], ARRAY['Bicipiti', 'Polpacci', 'Glutei', 'Femorali', 'Lombari', 'Dorso']::text[], ARRAY['Macchina']::text[], 'pull', 'bilaterale', 'free-exercise-db', 'Unlicense', 1, ARRAY['Recupero']::text[], '{}'::text[], '{}'::text[]),
-- fed:Hamstring-SMR · Foam roller femorali
('fed:Hamstring-SMR', 'Hamstring-SMR', 'Foam roller femorali', 'Recupero', 'Automassaggio', 'Principiante', NULL, ARRAY['In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position.', 'Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching.', 'Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], '{}'::text[], ARRAY['Foam roller']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero', 'Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Quadriceps-SMR · Foam roller quadricipiti
('fed:Quadriceps-SMR', 'Quadriceps-SMR', 'Foam roller quadricipiti', 'Recupero', 'Automassaggio', 'Intermedio', NULL, ARRAY['Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position.', 'Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides.']::text[], '{}'::text[], '{}'::text[], ARRAY['Quadricipiti']::text[], '{}'::text[], ARRAY['Foam roller']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero', 'Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Calves-SMR · Foam roller polpacci
('fed:Calves-SMR', 'Calves-SMR', 'Foam roller polpacci', 'Recupero', 'Automassaggio', 'Intermedio', NULL, ARRAY['Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position.', 'Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Polpacci']::text[], '{}'::text[], ARRAY['Foam roller']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero', 'Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Iliotibial_Tract-SMR · Foam roller bandelletta ileotibiale
('fed:Iliotibial_Tract-SMR', 'Iliotibial Tract-SMR', 'Foam roller bandelletta ileotibiale', 'Recupero', 'Automassaggio', 'Intermedio', NULL, ARRAY['Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you.', 'Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching.', 'Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.']::text[], '{}'::text[], '{}'::text[], ARRAY['Abduttori']::text[], '{}'::text[], ARRAY['Foam roller']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero', 'Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Piriformis-SMR · Foam roller piriforme
('fed:Piriformis-SMR', 'Piriformis-SMR', 'Foam roller piriforme', 'Recupero', 'Automassaggio', 'Intermedio', NULL, ARRAY['Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position.', 'Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.']::text[], '{}'::text[], '{}'::text[], ARRAY['Glutei']::text[], '{}'::text[], ARRAY['Foam roller']::text[], 'mobility', 'unilaterale', 'free-exercise-db', 'Unlicense', 2, ARRAY['Recupero', 'Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- fed:Childs_Pose · Posizione del bambino (child's pose)
('fed:Childs_Pose', 'Child''s Pose', 'Posizione del bambino (child''s pose)', 'Recupero', 'Allungamento', 'Principiante', NULL, ARRAY['Get on your hands and knees, walk your hands in front of you.', 'Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.', 'Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.']::text[], '{}'::text[], '{}'::text[], ARRAY['Lombari']::text[], ARRAY['Glutei', 'Dorso']::text[], '{}'::text[], 'mobility', 'bilaterale', 'free-exercise-db', 'Unlicense', 1, ARRAY['Recupero', 'Mobilità']::text[], '{}'::text[], '{}'::text[]),
-- auvi:nordic-hamstring-curl · Nordic hamstring curl
('auvi:nordic-hamstring-curl', 'Nordic Hamstring Curl', 'Nordic hamstring curl', 'Prevenzione', 'Femorali', 'Avanzato', 'istruzioni AUVI da validare dal preparatore', ARRAY['In ginocchio su un tappetino, caviglie bloccate da un compagno o da un supporto fisso; busto e cosce allineati.', 'Scendere in avanti il più lentamente possibile mantenendo anche estese (corpo in linea da ginocchia a testa).', 'Quando non si riesce più a frenare, accompagnare la caduta con le mani in posizione di piegamento.', 'Tornare alla posizione iniziale spingendo con le mani, con il minimo aiuto necessario.']::text[], '{}'::text[], '{}'::text[], ARRAY['Femorali']::text[], ARRAY['Glutei', 'Polpacci']::text[], ARRAY['Corpo libero']::text[], 'hinge', 'bilaterale', 'auvi', 'AUVI', 3, ARRAY['Forza', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Femorali']::text[]),
-- auvi:copenhagen-plank-short-lever · Copenhagen plank (leva corta)
('auvi:copenhagen-plank-short-lever', 'Copenhagen Plank (Short Lever)', 'Copenhagen plank (leva corta)', 'Prevenzione', 'Adduttori', 'Intermedio', 'istruzioni AUVI da validare dal preparatore', ARRAY['Plank laterale sull''avambraccio con il ginocchio della gamba superiore appoggiato su una panca.', 'Sollevare il bacino fino ad allineare spalle, anca e ginocchio; la gamba inferiore resta sotto la panca o si porta verso di essa.', 'Mantenere la posizione per il tempo prescritto, poi cambiare lato.']::text[], '{}'::text[], '{}'::text[], ARRAY['Adduttori']::text[], ARRAY['Addominali']::text[], ARRAY['Corpo libero']::text[], 'isometric', 'unilaterale', 'auvi', 'AUVI', 3, ARRAY['Forza', 'Stabilità', 'Prevenzione infortuni']::text[], '{}'::text[], ARRAY['Pubalgia/adduttori']::text[]),
