-- 1) aggancio delle righe già importate (stesso nome, slug ancora NULL)
UPDATE public.fitness_exercise_library AS fel SET slug = s.slug FROM _seed_ex s
  WHERE fel.slug IS NULL AND lower(fel.name) = lower(s.name)
    AND NOT EXISTS (SELECT 1 FROM public.fitness_exercise_library x WHERE x.slug = s.slug);

-- 2) upsert per slug: le righe nuove nascono senza immagine (image_url NULL, gen_status pending)
INSERT INTO public.fitness_exercise_library AS fel (slug, name, name_it, category, subcategory, muscle_group, equipment, difficulty, description,
  instructions, coaching_cues, common_mistakes, primary_muscles, secondary_muscles, equipment_tags, movement_pattern,
  laterality, source, source_license, is_custom, curated, football_relevance, performance_goals, position_relevance,
  injury_prevention, image_url, gen_status)
SELECT s.slug, s.name, s.name_it, s.category, s.subcategory, s.primary_muscles[1], s.equipment_tags[1], s.difficulty,
  CASE WHEN cardinality(s.instructions) = 0 THEN NULL
       WHEN s.note IS NOT NULL THEN '[' || s.note || '] ' || array_to_string(s.instructions, ' ')
       ELSE array_to_string(s.instructions, ' ') END,
  s.instructions, s.coaching_cues, s.common_mistakes, s.primary_muscles, s.secondary_muscles, s.equipment_tags,
  s.movement_pattern, s.laterality, s.source, s.source_license, false, true, s.football_relevance,
  s.performance_goals, s.position_relevance, s.injury_prevention, NULL, 'pending'
FROM _seed_ex s
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    name_it = EXCLUDED.name_it,
    category = EXCLUDED.category,
    subcategory = EXCLUDED.subcategory,
    muscle_group = EXCLUDED.muscle_group,
    equipment = EXCLUDED.equipment,
    difficulty = EXCLUDED.difficulty,
    description = COALESCE(fel.description, EXCLUDED.description),
    instructions = EXCLUDED.instructions,
    coaching_cues = CASE WHEN cardinality(EXCLUDED.coaching_cues) > 0 THEN EXCLUDED.coaching_cues ELSE fel.coaching_cues END,
    common_mistakes = CASE WHEN cardinality(EXCLUDED.common_mistakes) > 0 THEN EXCLUDED.common_mistakes ELSE fel.common_mistakes END,
    primary_muscles = EXCLUDED.primary_muscles,
    secondary_muscles = EXCLUDED.secondary_muscles,
    equipment_tags = EXCLUDED.equipment_tags,
    movement_pattern = EXCLUDED.movement_pattern,
    laterality = EXCLUDED.laterality,
    source = EXCLUDED.source,
    source_license = EXCLUDED.source_license,
    is_custom = false,
    curated = true,
    football_relevance = EXCLUDED.football_relevance,
    performance_goals = EXCLUDED.performance_goals,
    position_relevance = CASE WHEN cardinality(EXCLUDED.position_relevance) > 0 THEN EXCLUDED.position_relevance ELSE fel.position_relevance END,
    injury_prevention = EXCLUDED.injury_prevention;

-- 3) controllo: tutte le voci del seed devono esistere e risultare curate, altrimenti si annulla tutto
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.fitness_exercise_library fel JOIN _seed_ex s ON s.slug = fel.slug WHERE fel.curated;
  IF n <> 206 THEN RAISE EXCEPTION 'seed esercizi: attese 206 voci curate, trovate %', n; END IF;
END $$;

COMMIT;

-- verifica (sola lettura)
SELECT source, category, count(*) FROM public.fitness_exercise_library WHERE curated GROUP BY 1, 2 ORDER BY 1, 2;
